func (mmConsumeJobs *mQueueMockConsumeJobs) invocationsDone() bool {
	if len(mmConsumeJobs.expectations) == 0 && mmConsumeJobs.defaultExpectation == nil && mmConsumeJobs.mock.funcConsumeJobs == nil {
		return true
	}

	totalInvocations := mm_atomic.LoadUint64(&mmConsumeJobs.mock.afterConsumeJobsCounter)
	expectedInvocations := mm_atomic.LoadUint64(&mmConsumeJobs.expectedInvocations)

	return totalInvocations > 0 && (expectedInvocations == 0 || expectedInvocations == totalInvocations)
}

// ConsumeJobs implements mm_worker.Queue
func (mmConsumeJobs *QueueMock) ConsumeJobs(ctx context.Context, consumer string, block time.Duration) (da1 []storage.DeliveredJob, err error) {
	mm_atomic.AddUint64(&mmConsumeJobs.beforeConsumeJobsCounter, 1)
	defer mm_atomic.AddUint64(&mmConsumeJobs.afterConsumeJobsCounter, 1)

	mmConsumeJobs.t.Helper()

	if mmConsumeJobs.inspectFuncConsumeJobs != nil {
		mmConsumeJobs.inspectFuncConsumeJobs(ctx, consumer, block)
	}

	mm_params := QueueMockConsumeJobsParams{ctx, consumer, block}

	// Record call args
	mmConsumeJobs.ConsumeJobsMock.mutex.Lock()
	mmConsumeJobs.ConsumeJobsMock.callArgs = append(mmConsumeJobs.ConsumeJobsMock.callArgs, &mm_params)
	mmConsumeJobs.ConsumeJobsMock.mutex.Unlock()

	for _, e := range mmConsumeJobs.ConsumeJobsMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.da1, e.results.err
		}
	}

	if mmConsumeJobs.ConsumeJobsMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmConsumeJobs.ConsumeJobsMock.defaultExpectation.Counter, 1)
		mm_want := mmConsumeJobs.ConsumeJobsMock.defaultExpectation.params
		mm_want_ptrs := mmConsumeJobs.ConsumeJobsMock.defaultExpectation.paramPtrs

		mm_got := QueueMockConsumeJobsParams{ctx, consumer, block}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmConsumeJobs.t.Errorf("QueueMock.ConsumeJobs got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmConsumeJobs.ConsumeJobsMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.consumer != nil && !minimock.Equal(*mm_want_ptrs.consumer, mm_got.consumer) {
				mmConsumeJobs.t.Errorf("QueueMock.ConsumeJobs got unexpected parameter consumer, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmConsumeJobs.ConsumeJobsMock.defaultExpectation.expectationOrigins.originConsumer, *mm_want_ptrs.consumer, mm_got.consumer, minimock.Diff(*mm_want_ptrs.consumer, mm_got.consumer))
			}

			if mm_want_ptrs.block != nil && !minimock.Equal(*mm_want_ptrs.block, mm_got.block) {
				mmConsumeJobs.t.Errorf("QueueMock.ConsumeJobs got unexpected parameter block, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmConsumeJobs.ConsumeJobsMock.defaultExpectation.expectationOrigins.originBlock, *mm_want_ptrs.block, mm_got.block, minimock.Diff(*mm_want_ptrs.block, mm_got.block))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmConsumeJobs.t.Errorf("QueueMock.ConsumeJobs got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmConsumeJobs.ConsumeJobsMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmConsumeJobs.ConsumeJobsMock.defaultExpectation.results
		if mm_results == nil {
			mmConsumeJobs.t.Fatal("No results are set for the QueueMock.ConsumeJobs")
		}
		return (*mm_results).da1, (*mm_results).err
	}
	if mmConsumeJobs.funcConsumeJobs != nil {
		return mmConsumeJobs.funcConsumeJobs(ctx, consumer, block)
	}
	mmConsumeJobs.t.Fatalf("Unexpected call to QueueMock.ConsumeJobs. %v %v %v", ctx, consumer, block)
	return
}

